CAT = "cacesTechno"; SEG = "TEC"
# Technologie : sources d'énergie, batteries, GPL, composants, organes et dispositifs de
# sécurité, maintien au poste, réglages, équipements porte-charge.
# Sources : R489 annexe 2 (B), annexe 3/1 ; INRS ED 766, § 2.2 à 2.8 ; INRS ED 812, chap. 1.
Q = [
("Quel gaz dégage une batterie de traction au plomb pendant sa charge ?",
 "De l'hydrogène", ["Du monoxyde de carbone", "Du propane", "De l'azote"],
 "INRS ED 766, § 2.8 : la charge dégage de l'hydrogène, gaz explosif ; on charge dans un local bien aéré, sans flamme ni cigarette à proximité."),
("Jusqu'à quel niveau, au plus, peut-on décharger une batterie de traction selon l'INRS ?",
 "80 % de sa capacité", ["50 % de sa capacité", "95 % de sa capacité", "100 % de sa capacité"],
 "INRS ED 766, § 2.8 : ne pas décharger une batterie à plus de 80 % de sa capacité et la recharger en une seule fois."),
("Le niveau d'électrolyte d'une batterie est bas. Avec quoi faites-vous l'appoint ?",
 "Eau distillée", ["Acide sulfurique dilué", "Eau du robinet filtrée", "Liquide de refroidissement"],
 "INRS ED 766, § 2.8 : l'appoint se fait à l'eau distillée ou déminéralisée, en fin de charge et sans débordement ; on ne rajoute jamais d'acide."),
("À quel moment de la charge fait-on l'appoint d'eau d'une batterie ?",
 "À la fin de la charge", ["Avant de brancher", "Au milieu de la charge", "Pendant la conduite"],
 "INRS ED 766, § 2.8 : le plein d'eau distillée se fait à la fin de la charge, sans faire déborder l'électrolyte."),
("Pendant la charge d'une batterie de traction, le couvercle du coffre doit être :",
 "Ouvert", ["Fermé à clé", "Fermé mais déverrouillé", "Retiré du chariot"],
 "INRS ED 766, § 2.8 : on ouvre les couvercles de batterie pendant la charge pour évacuer les gaz ; en marche normale, le couvercle du coffre reste fermé."),
("Pourquoi ne pose-t-on jamais d'outil métallique sur une batterie ?",
 "Risque de court-circuit", ["Risque de rouille des bornes", "Risque de surcharge du chargeur", "Risque de perte d'électrolyte"],
 "INRS ED 766, § 2.8 : un outil ou une pièce métallique peut relier les bornes, provoquer un court-circuit, des étincelles et l'explosion de l'hydrogène."),
("Après être intervenu sur une batterie, que faites-vous ?",
 "Je me lave les mains", ["Je remets de l'acide", "Je débranche le chargeur", "Je resserre le mât"],
 "INRS ED 766, § 2.8 : on se lave les mains après toute intervention, car l'électrolyte contient de l'acide sulfurique corrosif."),
("Quelle température les parois d'un réservoir de GPL ne doivent-elles jamais dépasser ?",
 "50 °C", ["30 °C", "80 °C", "100 °C"],
 "INRS ED 766, § 2.7 : les parois des réservoirs ou bouteilles de GPL ne doivent jamais dépasser 50 °C ; on évite donc le stationnement prolongé au soleil ou près d'une source de chaleur."),
("Où change-t-on la bouteille de GPL d'un chariot ?",
 "Dans une zone aérée prévue", ["Dans l'allée la plus proche", "Dans le local de charge des batteries", "Sur le quai de chargement"],
 "INRS ED 766, § 2.7 : l'échange se fait dans une zone réservée, de préférence à l'air libre ou dans un local bien aéré, loin de toute flamme, moteur arrêté, par du personnel formé."),
("Avant de faire le plein de carburant d'un chariot thermique, que devez-vous faire ?",
 "Arrêter le moteur", ["Laisser tourner au ralenti", "Lever la fourche", "Allumer les phares"],
 "INRS ED 766, § 2.6 : toujours arrêter le moteur, ne pas fumer et faire le plein aux emplacements prévus."),
("Sur quels chariots le système de retenue (ceinture ou portillon) est-il exigé ?",
 "Ceux pouvant se renverser", ["Seulement ceux de plus de 6 t", "Seulement les tout-terrain", "Ceux qui roulent dehors"],
 "INRS ED 766, § 2.2.2 : s'il existe un risque que le conducteur soit écrasé entre le chariot et le sol en cas de renversement, le chariot doit avoir un système de retenue (art. R4324-35)."),
("À partir de quelle hauteur de levée un protège-conducteur contre les chutes d'objets est-il obligatoire ?",
 "1,80 m", ["1,20 m", "2,50 m", "3 m"],
 "INRS ED 766, § 2.2.2 : tout chariot dont la hauteur de levée dépasse 1,80 m doit être muni d'un protège-conducteur contre la chute d'objets."),
("À quoi sert le dosseret de charge ?",
 "Retenir la charge", ["Équilibrer le contrepoids", "Freiner la descente du mât", "Guider les chaînes du mât"],
 "INRS ED 766, § 2.2.2 : le dosseret empêche les éléments de la charge de tomber sur le poste de conduite ; son maillage dépend des plus petits éléments transportés."),
("Pourquoi le chariot a-t-il une clé de contact ou un badge ?",
 "Empêcher un usage non autorisé", ["Compter les heures de travail", "Couper la batterie la nuit", "Serrer le frein de parc"],
 "INRS ED 766, § 2.2 : la clé de contact ou un dispositif équivalent empêche une personne non autorisée de conduire le chariot."),
("Sur un chariot frontal en porte-à-faux, qu'est-ce qui équilibre la charge ?",
 "Le contrepoids", ["Les stabilisateurs latéraux", "Le dosseret de charge", "Les longerons avant"],
 "INRS ED 812 : sur le chariot frontal, la charge et l'ensemble élévateur sont en porte-à-faux devant l'essieu avant ; le contrepoids à l'arrière assure la stabilité."),
("Pour circuler, un chariot à mât rétractable ramène son mât. Dans quel but ?",
 "Stabiliser le chariot", ["Gagner de la vitesse en allée", "Lever la charge plus haut", "Mieux voir derrière soi"],
 "INRS ED 812 : rétracter l'ensemble élévateur ramène la charge à l'intérieur du polygone de sustentation, ce qui stabilise le chariot et réduit sa longueur."),
("Quel organe soulève le tablier et les fourches le long du mât ?",
 "Le vérin de levée", ["Le vérin d'inclinaison", "Le vérin de direction", "Le vérin de frein"],
 "R489, annexe 2 (B) : le mécanisme d'élévation repose sur un ou des vérins de levée et des chaînes ; les vérins d'inclinaison font basculer le mât vers l'avant ou l'arrière."),
("Quel mouvement donne le vérin d'inclinaison ?",
 "Pencher le mât", ["Monter la fourche", "Écarter les bras", "Tourner les roues"],
 "R489, annexe 2 (B) : les vérins d'inclinaison font basculer le mât vers l'avant pour poser la charge ou vers l'arrière pour la caler pendant le transport."),
("Un chariot reçoit une pince à bobines à la place de sa fourche. Que devient sa capacité ?",
 "Elle diminue", ["Elle augmente", "Elle ne change pas", "Elle double"],
 "INRS ED 766, § 2.4 : un nouvel équipement porte-charge modifie la stabilité ; en règle générale la capacité diminue et le conducteur doit être informé des nouvelles capacités."),
("Une rallonge de fourche peut dépasser la longueur du bras de fourche de :",
 "50 % au plus", ["25 % au plus", "75 % au plus", "100 % au plus"],
 "INRS ED 812 : la rallonge ne doit pas dépasser 50 % du bras de fourche, et la distance de centre de gravité prévue doit être respectée."),
("Pourquoi régler le poids sur un siège à suspension ?",
 "Absorber les vibrations", ["Abaisser le centre de gravité", "Freiner plus fort", "Gagner en vitesse"],
 "INRS ED 766, § 4.2 : le réglage du poids d'un siège suspendu permet à la suspension d'absorber les vibrations verticales, cause de troubles du dos."),
("Quel est l'atout d'un chariot électrique par rapport à un thermique en entrepôt fermé ?",
 "Aucun gaz d'échappement", ["Une vitesse plus élevée", "Une plus grande autonomie", "Aucune recharge à prévoir"],
 "INRS ED 812 : les chariots thermiques rejettent des gaz polluants et font plus de bruit ; l'électrique n'a pas d'échappement, ce qui convient aux locaux fermés."),
("Dans une zone à risque d'explosion (ATEX), quel chariot peut-on utiliser ?",
 "Un chariot conçu pour la zone", ["Tout chariot électrique", "Tout chariot au GPL", "Un chariot sans cabine fermée"],
 "INRS ED 766, § 2.2.3 : les chariots qui circulent dans des locaux à risque d'explosion ou d'incendie doivent avoir des protections adaptées à la zone ATEX concernée."),
("À partir de quelle usure un bras de fourche ne doit-il plus être utilisé, selon l'INRS ?",
 "Plus de 10 %", ["Plus de 30 %", "Plus de 50 %", "Plus de 2 %"],
 "INRS ED 812 : il est recommandé de ne plus utiliser une fourche dont l'usure dépasse 10 % ; les bras sont contrôlés pour les fissures et les déformations."),
]
